# Use zip_longest with a sentinel; if a sentinel appears before all
    # iterables are exhausted, the lengths are unequal.
    for items in zip_longest(*iters, fillvalue=sentinel):
        if any(item is sentinel for item in items):
            if not all(item is sentinel for item in items):
                raise UnequalIterablesError(
                    "Iterables have different lengths"
                )
            return
        yield tuple(items)

